import json, re

# Check the monitor log for SSH results containing ced_r5 and extract_r3 metric dicts
with open('logs/workers/worker_monitor_grpo_training_health_check_20260514T145320.log', 'r') as f:
    lines = f.readlines()

print(f"Lines: {len(lines)}")

for i, line in enumerate(lines):
    line = line.strip()
    if not line:
        continue
    try:
        d = json.loads(line)
        if d.get('type') == 'user':
            content = d.get('message', {}).get('content', [])
            if isinstance(content, list):
                for item in content:
                    if isinstance(item, dict):
                        raw = str(item.get('content', ''))
                        if "'loss'" in raw and "'grad_norm'" in raw and "'epoch'" in raw:
                            # Found metric dicts
                            blocks = re.findall(r"\{'loss': [-0-9eE.]+,.*?'epoch': [0-9.]+\}", raw)
                            if len(blocks) > 5:
                                print(f"LINE {i}: {len(blocks)} metric blocks found")
                                # Check which experiment based on ced_reward presence
                                has_ced = "'rewards/ced_reward/mean'" in raw
                                has_flat_nli = "'rewards/flat_nli_reward" in raw
                                if has_ced:
                                    print(f"  -> CED experiment (has ced_reward)")
                                elif has_flat_nli:
                                    print(f"  -> FlatNLI experiment")
                                else:
                                    print(f"  -> Extract-only experiment (no ced/flat_nli)")

                                # Show first and last block
                                print(f"  First block: {blocks[0][:200]}...")
                                print(f"  Last block: {blocks[-1][:200]}...")
                                print()
    except json.JSONDecodeError:
        continue
